var results = [];

// ════════════════════════════════════════
// 1. CLEAN TEXT
// ════════════════════════════════════════
function cleanText(text) {
  if (!text) return '';

  text = text.replace(
    /^[\s\S]*?·\n\s*(?:\d+\s*(?:phút|giờ|ngày|tuần|tháng|giây)|(?:\d{1,2}\s+Tháng\s+\d{1,2}[^\n]*))\s*\n\s*·\s*\n/i,
    ''
  );

  text = text.replace(
    /\n?\s*(?:Tất cả cảm xúc[\s\S]*|\d+\s*(?:bình luận|lượt chia sẻ)\s*\nThích[\s\S]*|(?:^|\n)Thích\nBình luận\nChia sẻ[\s\S]*)/im,
    ''
  );

  var boldMap = {
    '𝐀':'A','𝐁':'B','𝐂':'C','𝐃':'D','𝐄':'E','𝐅':'F','𝐆':'G','𝐇':'H',
    '𝐈':'I','𝐉':'J','𝐊':'K','𝐋':'L','𝐌':'M','𝐍':'N','𝐎':'O','𝐏':'P',
    '𝐐':'Q','𝐑':'R','𝐒':'S','𝐓':'T','𝐔':'U','𝐕':'V','𝐖':'W','𝐗':'X',
    '𝐘':'Y','𝐙':'Z','𝐚':'a','𝐛':'b','𝐜':'c','𝐝':'d','𝐞':'e','𝐟':'f',
    '𝐠':'g','𝐡':'h','𝐢':'i','𝐣':'j','𝐤':'k','𝐥':'l','𝐦':'m','𝐧':'n',
    '𝐨':'o','𝐩':'p','𝐪':'q','𝐫':'r','𝐬':'s','𝐭':'t','𝐮':'u','𝐯':'v',
    '𝐰':'w','𝐱':'x','𝐲':'y','𝐳':'z','𝟎':'0','𝟏':'1','𝟐':'2','𝟑':'3',
    '𝟒':'4','𝟓':'5','𝟔':'6','𝟕':'7','𝟖':'8','𝟗':'9'
  };
  text = text.split('').map(function(c) { return boldMap[c] || c; }).join('');

  return text.replace(/\n{3,}/g, '\n\n').trim();
}


// ════════════════════════════════════════
// 2. NGÀY ĐĂNG
// ════════════════════════════════════════
function extractNgayDang(post) {
  var text = post.text || '';
  var scrapedDate = post.scrapedAt
    ? new Date(post.scrapedAt).toISOString().split('T')[0]
    : new Date().toISOString().split('T')[0];

  var timeMatch = text.match(/·\n(\d+\s*(?:phút|giờ|giây))\s*\n/i);
  var dateMatch = text.match(/·\n(\d{1,2}\s+Tháng\s+\d{1,2}(?:\s+lúc\s+[\d:]+)?)\s*\n/i);
  var daysMatch = text.match(/·\n(\d+)\s*ngày\s*\n/i);
  var weekMatch = text.match(/·\n(\d+)\s*tuần\s*\n/i);

  if (timeMatch) return scrapedDate;
  if (dateMatch) return dateMatch[1].trim();
  if (daysMatch) {
    var d1 = new Date(post.scrapedAt || new Date());
    d1.setDate(d1.getDate() - parseInt(daysMatch[1]));
    return d1.toISOString().split('T')[0];
  }
  if (weekMatch) {
    var d2 = new Date(post.scrapedAt || new Date());
    d2.setDate(d2.getDate() - parseInt(weekMatch[1]) * 7);
    return d2.toISOString().split('T')[0];
  }
  return (post.postTime && post.postTime.trim()) ? post.postTime.trim() : scrapedDate;
}


// ════════════════════════════════════════
// 3. ĐỊA CHỈ
// ════════════════════════════════════════
function normalizeAddr(str) {
  if (!str) return '';
  str = str.replace(/^[•\-\*\s\[]+/, '');
  str = str.replace(/[\]\s]+$/, '');
  str = str.replace(/\bTPHCM\b/gi, 'TP. Hồ Chí Minh');
  str = str.replace(/\bTP\.\s*HCM\b/gi, 'TP. Hồ Chí Minh');
  str = str.replace(/\bTP\.HCM\b/gi, 'TP. Hồ Chí Minh');
  str = str.replace(/\bHCM\b/g, 'TP. Hồ Chí Minh');
  str = str.replace(/\bHN\b/g, 'Hà Nội');
  str = str.replace(/\bĐN\b/g, 'Đà Nẵng');
  str = str.replace(/\bBD\b/g, 'Bình Dương');
  str = str.replace(/\bHP\b/g, 'Hải Phòng');
  str = str.replace(/TP\.\s+TP\./gi, 'TP.');
  str = str.replace(/^làm\s*việc\s+/i, '');
  str = str.replace(/[,;\s\.]+$/, '').trim();
  return str;
}

function isValidAddr(str, hasKeyword) {
  if (!str || str.length < 3) return false;
  if (str.includes('@') || str.includes('http')) return false;
  if (/thứ\s*\d|chủ\s*nhật|giờ\s*hành\s*chính|sáng|chiều/i.test(str)) return false;
  if (hasKeyword) return true;
  var geoWords = [
    'hà nội', 'hồ chí minh', 'đà nẵng', 'hải phòng', 'cần thơ',
    'bình dương', 'đồng nai', 'nghệ an', 'thanh hóa', 'quảng ninh',
    'thái nguyên', 'nam định', 'khánh hòa', 'lâm đồng', 'bắc ninh',
    'sài gòn', 'thủ đức', 'tân bình', 'hoàng mai', 'thanh xuân',
    'đống đa', 'cầu giấy', 'mỹ đình', 'nam từ liêm', 'duy tân',
    'gò vấp', 'tân phú', 'bình thạnh', 'hạ long', 'thanh trì',
    'ninh kiều', 'biên hòa', 'vĩnh hưng', 'khuất duy tiến',
    'thạch thất', 'hoàng quốc việt', 'nguyễn trãi', 'lê văn lương',
    'phạm văn đồng', 'trần duy hưng', 'xuân thủy', 'cầu diễn',
    'nguyễn xiển', 'lê đức thọ', 'nguyễn huy tưởng', 'duy tân',
    'quận', 'huyện', 'phường', 'đường', 'phố', 'ngõ', 'ngách',
    'tòa', 'lô', 'số ', 'tp.', 'tỉnh',
    'q1','q2','q3','q4','q5','q6','q7','q8','q9','q10','q11','q12',
    'q.1','q.2','q.3','q.4','q.5','q.6','q.7','q.8','q.9','q.10','q.11','q.12'
  ];
  var lower = str.toLowerCase();
  return geoWords.some(function(w) { return lower.indexOf(w) !== -1; });
}

function extractDiaChi(text) {
  if (!text) return '';
  var m, addr;

  // ── P1: Keyword + giá trị CÙNG DÒNG ──
  var kwPatterns = [
    /(?:•\s*)?(?:\*{1,2})?(?:địa\s*(?:chỉ|điểm)(?:\s*làm\s*việc)?)\s*[:\-]\s*([^\n]{3,150})/i,
    /(?:làm\s*việc\s*tại|trụ\s*sở)\s*[:\-]\s*([^\n]{3,120})/i,
    /(?:\*\s*)?ĐỊA\s*CHỈ\s*[:\-]\s*([^\n]{3,120})/i,
  ];
  for (var i = 0; i < kwPatterns.length; i++) {
    m = text.match(kwPatterns[i]);
    if (m && m[1]) {
      addr = normalizeAddr(m[1].trim());
      if (isValidAddr(addr, true)) return addr;
    }
  }

  // ── P2: Keyword trên dòng riêng, địa chỉ dòng tiếp ──
  m = text.match(/(?:địa\s*(?:chỉ|điểm)(?:\s*làm\s*việc)?|ĐỊA\s*ĐIỂM\s*LÀM\s*VIỆC)[:\s]*\n\s*(?:[-•]\s*)?([^\n]{3,150})/i);
  if (m && m[1]) {
    addr = normalizeAddr(m[1].trim());
    if (isValidAddr(addr, true)) return addr;
  }

  // ── P3: "khu vực X, Y" ──
  m = text.match(/khu\s*vực\s+([^\n,]{3,40},\s*[^\n]{3,40})/i);
  if (m && m[1]) {
    addr = normalizeAddr(m[1].trim());
    if (isValidAddr(addr, false)) return addr;
  }

  // ── P4: "(LOẠI) - khu vực X" hoặc địa danh cuối tiêu đề ──
  m = text.match(/\([^)]+\)\s*-\s*(?:khu\s*vực\s+)?([^\n]{5,60})/i);
  if (m && m[1]) {
    addr = normalizeAddr(m[1].trim());
    if (isValidAddr(addr, false)) return addr;
  }

  // ── P4b: "ĐỊA DANH/ĐỊA DANH (VỊ TRÍ)" ở dòng đầu ──
  // VD: "THẠCH THẤT/HÀ NỘI (HR CHIEF)" → "Thạch Thất/Hà Nội"
  // VD: "HCM/HÀ NỘI" → "TP. Hồ Chí Minh/Hà Nội"
  var firstLine4b = text.split('\n')[0] || '';
  m = firstLine4b.match(/^([^\n(\[\]]{3,30}\/[^\n(\[\]]{2,25})(?:\s*\([^)]*\))?$/);
  if (m && m[1]) {
    addr = normalizeAddr(m[1].trim());
    if (addr.length <= 40 && isValidAddr(addr, false)) return addr;
  }

  // ── P5: Phần cuối dòng đầu sau dấu - hoặc – ──
  var firstLine = text.split('\n')[0] || '';
  var parts = firstLine.split(/\s*[-–—]\s*/);
  if (parts.length >= 2) {
    var lastPart = normalizeAddr(parts[parts.length - 1].trim());
    if (isValidAddr(lastPart, false) && lastPart.length <= 30) {
      return lastPart;
    }
  }

  // ── P6: Bracket đầu text ──
  m = text.match(/^\[([^\]]{2,60})\]/);
  if (m && m[1]) {
    var inner = m[1];
    if (!/tuyển|dụng|group/i.test(inner)) {
      addr = normalizeAddr(inner.trim());
      // FIX: strip text thừa sau Q\d+ trước khi swap (VD: "TP. Hồ Chí Minh Q1 Tuyển...")
      addr = addr.replace(/^(TP\.[^\d,]+)\s+(Q\d+).*$/i, '$2, $1');
      addr = addr.replace(/^(Q\d+)[^,]*,\s*(TP\..+)$/, '$1, $2'); // giữ sạch nếu đã đúng thứ tự
      if (isValidAddr(addr, false)) return addr;
    } else {
      var dashPart = inner.match(/-\s*([^-\]]+?)(?:\s+TUYỂN|\s+CẦN|$)/i);
      if (dashPart && dashPart[1]) {
        addr = normalizeAddr(dashPart[1].trim());
        if (isValidAddr(addr, false)) return addr;
      }
      var lamViec = inner.match(/làm\s*việc\s+(.+)/i);
      if (lamViec && lamViec[1]) {
        addr = normalizeAddr(lamViec[1].trim());
        if (isValidAddr(addr, false)) return addr;
      }
    }
  }

  // ── P7: Số nhà + đường + quận + tỉnh ──
  m = text.match(/(\d+[A-Za-z\/\-]*\s+[^\n,@]{3,40},\s*[^\n,@]{3,40},\s*[^\n@]{3,40})/);
  if (m && m[1]) {
    addr = normalizeAddr(m[1].trim());
    if (isValidAddr(addr, false) && !addr.includes('@')) return addr;
  }

  // ── P8: Tòa nhà X, địa chỉ ──
  m = text.match(/tòa\s+nhà\s+[^\n,]{2,30},\s*[^\n]{5,80}/i);
  if (m && m[0]) {
    addr = normalizeAddr(m[0].trim());
    if (isValidAddr(addr, false)) return addr;
  }

  // ── P9: Quận/khu vực + tỉnh thành cụ thể ──
  var cityList = [
    'TP\\. Hồ Chí Minh', 'Hà Nội', 'Đà Nẵng', 'Hải Phòng',
    'Bình Dương', 'Cần Thơ', 'Đồng Nai', 'Nghệ An',
    'Thanh Hóa', 'Quảng Ninh'
  ];
  for (var c = 0; c < cityList.length; c++) {
    var cityRe = new RegExp('(?:^|\\n)\\s*([^\\n\\d@,]{2,30},\\s*' + cityList[c] + ')\\s*(?:\\n|$)', 'im');
    m = text.match(cityRe);
    if (m && m[1]) {
      addr = normalizeAddr(m[1].trim());
      if (isValidAddr(addr, false)) return addr;
    }
  }

  return '';
}


// ════════════════════════════════════════
// 4. TÊN CÔNG TY
// ════════════════════════════════════════

var GEO_NAMES = [
  'HN','HCM','ĐN','BD','HP','CT',
  'Hà Nội','Sài Gòn','TPHCM','TP.HCM','TP. HCM',
  'Hồ Chí Minh','Đà Nẵng','Hải Phòng','Bình Dương',
  'HÀ NỘI','SÀI GÒN','ĐÀ NẴNG','HẢI PHÒNG','BÌNH DƯƠNG',
  'Cần Thơ','CẦN THƠ','Đồng Nai','ĐỒNG NAI',
  'TPHCM','TP.HCM',
  'HOÀNG QUỐC VIỆT','Hoàng Quốc Việt',
  'NGUYỄN TRÃI','PHẠM VĂN ĐỒNG','LÊ VĂN LƯƠNG',
  'TRẦN DUY HƯNG','XUÂN THỦY','DUY TÂN',
  'NGUYỄN XIỂN','LÊ ĐỨC THỌ'
];

function isGeoName(name) {
  var trimmed = name.trim();
  for (var g = 0; g < GEO_NAMES.length; g++) {
    if (trimmed === GEO_NAMES[g]) return true;
  }
  return false;
}

function isValidCompanyName(name) {
  if (!name || name.length < 2) return false;
  if (name.split(' ').length > 7) return false;
  if (/^\d/.test(name)) return false;
  if (isGeoName(name)) return false;

  var invalidPatterns = [
    /\[/, /\]/,
    /tiêu\s*đề/i,
    /họ\s*tên/i,
    /vị\s*trí\s*ứng/i,
    /tên\s*công\s*ty/i,
    /xem\s*thêm/i,
    /nếu\s*bạn/i,
    /khu\s*vực/i,
    /team\s*mình/i,
    /không\s*yêu\s*cầu/i,
    /thứ\s*\d/i,
    /chủ\s*nhật/i
  ];
  for (var i = 0; i < invalidPatterns.length; i++) {
    if (invalidPatterns[i].test(name)) return false;
  }
  return true;
}

function extractTenCongTy(text) {
  if (!text) return '';

  var blacklistWords = [
    'gmail','yahoo','hotmail','tham gia','bình luận','chia sẻ','thích',
    'xem thêm','tác giả','facebook','youtube','tiktok','mxh',
    'để hoàn thiện','trang bị','mình đã','ứng viên','ứng tuyển',
    'môi trường','quyền lợi','yêu cầu','mô tả','không yêu cầu',
    'phúc lợi','công việc chính',
    'nếu bạn','chúng tôi','team mình','khu vực',
    'tuyển dụng video','tuyển dụng nhân','tuyển dụng việc'
  ];

  function isBlack(s) {
    var lower = s.toLowerCase();
    return blacklistWords.some(function(b) { return lower.indexOf(b) !== -1; });
  }

  function clean(s) {
    return s
      .replace(/\s*\([^)]*\)\s*$/, '')
      .replace(/\s+/g, ' ')
      .replace(/[:\-\s!]+$/, '')
      .trim();
  }

  function tryReturn(candidate) {
    var name = clean(candidate);
    if (!name) return null;
    if (!isValidCompanyName(name)) return null;
    if (isBlack(name)) return null;
    // Reject neu sau normalize la dia danh hop le
    // VD: "HCM Q1" -> normalizeAddr -> "TP. Ho Chi Minh Q1" -> isValidAddr -> true -> reject
    var nameNorm = normalizeAddr(name);
    if (nameNorm !== name && isValidAddr(nameNorm, false)) return null;
    return name;
  }

  var lines = text.split('\n').map(function(l) { return l.trim(); }).filter(function(l) { return l.length > 0; });
  var firstLine = lines[0] || '';
  var firstLineClean = firstLine.replace(/\s*\([^)]*\)\s*$/, '').trim();
  var m, name;

  // ── P1: [TÊN TUYỂN...] ── chỉ search trong 300 ký tự đầu
  var textHead = text.substring(0, 300);
  m = textHead.match(/\[([^\]]{2,40})\]\s+(?:TUYỂN|CẦN\s+TUYỂN)/i);
  if (m && m[1]) {
    var namePart = m[1].split(/\s*-\s*/)[0];
    name = tryReturn(namePart);
    if (name) return name;
  }
  m = textHead.match(/\[([^\]]{2,60}?)(?:\s+TUYỂN|\s+CẦN\s+TUYỂN)/i);
  if (m && m[1]) {
    var namePart1b = m[1].split(/\s*[-–]\s*/)[0].trim();
    name = tryReturn(namePart1b);
    if (name) return name;
  }

  // ── P2: [TÊN] đứng riêng ──
  m = text.match(/^\[([^\]]{2,40})\](?!\s*(?:tuyển|cần|mô\s*tả))/i);
  if (m && m[1]) {
    var bracketContent = m[1].trim();
    // Normalize trước khi check geo (VD: "HCM Q1" → "TP. Hồ Chí Minh Q1")
    var bracketNorm = normalizeAddr(bracketContent);
    var isGeo = isGeoName(bracketContent) ||
                isGeoName(bracketNorm) ||
                isValidAddr(bracketNorm, false) ||
                /làm việc|tuyển dụng|group|ứng tuyển/i.test(bracketContent);
    if (!isGeo) {
      name = tryReturn(bracketContent);
      if (name) return name;
    }
  }

  // ── P3: **Công ty: TÊN ──
  m = text.match(/\*{1,2}công\s*ty\s*[:\s]+([^\n*\-]{2,50})/i);
  if (m && m[1]) {
    name = tryReturn(m[1]);
    if (name) return name;
  }

  // ── P4: Công ty TNHH/CP TÊN tuyển ──
  m = text.match(/công\s*ty\s+(?:tnhh\s+|cổ\s*phần\s+|cp\s+|mtv\s+)?([^\n,\-]{2,50}?)\s+tuyển/i);
  if (m && m[1]) {
    name = tryReturn(m[1]);
    if (name) return name;
  }

  // ── P5: LĨNH VỰC X - TÊN TUYỂN ──
  m = text.match(/lĩnh\s*vực[^\n]*-\s*([^\n]{2,40}?)\s+tuyển/i);
  if (m && m[1]) {
    name = tryReturn(m[1]);
    if (name) return name;
  }

  // ── P6: TÊN - TUYỂN DỤNG (dòng đầu) ──
  m = firstLineClean.match(/^(.{2,50}?)\s*[-–]\s*(?:TUYỂN|CẦN TUYỂN)/);
  if (m && m[1]) {
    name = tryReturn(m[1]);
    if (name) return name;
  }

  // ── P6b: TÊN ĐANG TÌM BẠN / TÊN ĐANG TUYỂN ──
  m = text.match(/(?:^|\n)\s*([A-ZÀ-ỹ][A-ZÀ-ỹ ]{1,30}[A-ZÀ-ỹ])\s+ĐANG\s+(?:TÌM|TUYỂN)/);
  if (m && m[1]) {
    name = tryReturn(m[1].trim());
    if (name) return name;
  }

  // ── P9: "X là trung tâm/công ty/tập đoàn" ──
  m = text.match(/([A-Z][A-Z ]{0,20}[A-Z])\s+là\s+(?:trung\s*tâm|công\s*ty|tập\s*đoàn|thương\s*hiệu)/);
  if (m && m[1]) {
    var candidate9 = m[1].trim();
    if (!/chúng\s*tôi|đây|bạn|ứng\s*viên/i.test(candidate9)) {
      name = tryReturn(candidate9);
      if (name) return name;
    }
  }

  // ── P7: TÊN TUYỂN ... (dòng đầu) ──
  var firstForP7 = firstLineClean.replace(/^\[[^\]]*\]\s*/, '').trim();
  m = firstForP7.match(/^(.+?)\s+(?:TUYỂN\s+DỤNG|TUYỂN\s+GẤP|CẦN\s+TUYỂN\s+GẤP|CẦN\s+TUYỂN|TUYỂN)/);
  if (m && m[1]) {
    name = tryReturn(m[1]);
    if (name) return name;
  }

  // ── P8: Dòng IN HOA ngắn đứng TRƯỚC dòng có chữ TUYỂN ──
  for (var i = 0; i < lines.length - 1; i++) {
    var curr = lines[i];
    var next = lines[i + 1];
    if (/^[#\d\-•\*\[\@]/.test(curr)) continue;
    if (curr.split(' ').length > 6) continue;
    if (curr.length < 2 || curr.length > 60) continue;
    if (curr !== curr.toUpperCase()) continue;
    if (!/tuyển/i.test(next)) continue;
    name = tryReturn(curr);
    if (name) return name;
  }

  return '';
}


// ════════════════════════════════════════
// 5. MAIN
// ════════════════════════════════════════
var GENERIC_DOMAINS = ['gmail','yahoo','hotmail','outlook','icloud'];

function capitalizeDomain(domain) {
  if (domain.indexOf('-') !== -1) return domain;
  return domain.toUpperCase();
}

var SKIP_DOMAIN_KEYWORDS = ['school','edu','ac','gov','org','uni','college','giadinh'];
function isSkipDomain(domain) {
  var lower = domain.toLowerCase();
  return SKIP_DOMAIN_KEYWORDS.some(function(s) { return lower.indexOf(s) !== -1; });
}

var allItems = $input.all();
for (var idx = 0; idx < allItems.length; idx++) {
  var item = allItems[idx];
  try {
    var jsonString = item.json.data || item.json;
    var parsed = JSON.parse(
      typeof jsonString === 'string' ? jsonString : JSON.stringify(jsonString)
    );

    for (var j = 0; j < parsed.length; j++) {
      var post = parsed[j];
      var cleaned = cleanText(post.text);

      var tenCongTy = extractTenCongTy(cleaned);

      if (!tenCongTy && post.emails && post.emails.length > 0) {
        var emailParts = (post.emails[0].split('@')[1] || '').split('.');
        var emailDomain = emailParts[0].toLowerCase();
        if (emailDomain &&
            GENERIC_DOMAINS.indexOf(emailDomain) === -1 &&
            !isSkipDomain(emailDomain)) {
          tenCongTy = capitalizeDomain(emailDomain);
        }
      }

      results.push({
        json: {
          postId:    post.postId,
          postUrl:   post.postUrl,
          groupName: post.groupName,
          email:     (post.emails || []).join(', '),
          phone:     (post.phones || []).join(', '),
          ngayDang:  extractNgayDang(post),
          tenCongTy: tenCongTy,
          diaChi:    extractDiaChi(cleaned),
          scrapedAt: post.scrapedAt,
          text:      cleaned
        }
      });
    }
  } catch(e) {
    results.push({ json: { error: e.message } });
  }
}

return results;

// Lấy tất cả items từ cả 2 input
const allItems = $input.all();

// Phân loại: item có 'Link bài viết' = từ Sheet, item có 'postUrl' = từ Lọc trường1
const sheetUrls = new Set(
  allItems
    .filter(i => i.json['Link bài viết'] !== undefined)
    .map(i => (i.json['Link bài viết'] || '').trim())
    .filter(Boolean)
);

// Chỉ xử lý items từ Lọc trường1 (có postUrl)
const newItems = allItems.filter(i => i.json['postUrl'] !== undefined);

return newItems.map(item => {
  const postUrl = (item.json['postUrl'] || '').trim();
  return {
    json: {
      ...item.json,
      isDuplicate: sheetUrls.has(postUrl)
    }
  };
});
